package com.skillsync.user;
import jakarta.persistence.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String email; @Column(nullable=false) private String password; private String fullName; private String department; private Double cgpa; @Column(length=3000) private String skills=""; @Column(name="account_role",length=20) private String accountRole="STUDENT"; public User(){} public User(String email,String password,String fullName){this.email=email;this.password=password;this.fullName=fullName;} public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getDepartment(){return department;} public Double getCgpa(){return cgpa;} public String getSkills(){return skills==null?"":skills;} public void setSkills(String v){skills=v==null?"":v;} public void setDepartment(String v){department=v;} public void setCgpa(Double v){cgpa=v;} public String getAccountRole(){return accountRole==null||accountRole.isBlank()?"STUDENT":accountRole;} public void setAccountRole(String v){accountRole=v;} }
